q=A.B(e,A.baJ(q,B.L,3,!1,B.L,B.aEQ,e,A.a([A.Kh(B.a76,f.fC(a0,"Wer ist Kkaebi?","Who is Kkaebi?","\u0915\u0948\u092c\u0940 \u0915\u094c\u0928 \u0939\u0948?","\u30af\u30b1\u30d3\u3068\u306f\uff1f","\uae68\ube44\ub294 \ub204\uad6c?","\u5409\u9b3c\u662f\u8c01\uff1f")),A.Kh(B.a7m,f.fC(a0,"DOK-KEY Anleitung","App Guide",c,"DOK-KEY \u8aac\u660e\u66f8","DOK-KEY \ub3c4\uc6c0\ub9d0","\u7cfb\u7edf\u8bf4\u660e\u4e66"))],s),B.xY),B.f,B.iu,e,e,e,e,e,e,e,e,e,e)
p=f.d
o=f.fC(a0,"Herkunft & Entstehung von Kkaebi","Origin of Kkaebi","\u0915\u0948\u092c\u0940 \u0915\u0940 \u0909\u0924\u094d\u092a\u0924\u094d\u0924\u093f \u0914\u0930 \u091c\u0928\u094d\u092e","\u30af\u30b1\u30d3\u306e\u7531\u6765\u3068\u8a95\u751f","\uae68\ube44\uc758 \uc720\ub798\uc640 \ud0c4\uc0dd","\u5409\u9b3c\u7684\u6e0a\u6e90\u4e0e\u8bde\u751f")
